from typing import List, Optional

class RunningStats:
    """Maintain sum/mean/min/max incrementally over appended values.

    Examples:
        >>> rs = RunningStats()
        >>> rs.append(3); rs.append(1); rs.append(4)
        >>> rs.total
        3
        >>> round(rs.mean(), 4)
        2.6667
        >>> rs.min()
        1
        >>> rs.max()
        4
    """
    def __init__(self) -> None:
        self.items: List[float] = []
        self.total: float = 0.0
        self._min: Optional[float] = None
        self._max: Optional[float] = None

    def append(self, value: float) -> None:
        self.items.append(value)
        self.total += value
        if self._min is None or value < self._min:
            self._min = value
        if self._max is None or value > self._max:
            self._max = value

    def mean(self) -> float:
        if not self.items:
            raise ValueError("no values")
        return self.total / len(self.items)

    def min(self) -> float:
        if self._min is None:
            raise ValueError("no values")
        return self._min

    def max(self) -> float:
        if self._max is None:
            raise ValueError("no values")
        return self._max

from typing import List, Tuple, Optional, Any
from bisect import bisect_left

class SparseList:
    """A sparse list storing only the populated indices.

    Examples:
        >>> s = SparseList()
        >>> s.set(3, 'a'); s.set(7, 'b')
        >>> s.get(3)
        'a'
        >>> s.get(7)
        'b'
        >>> s.get(0) is None
        True
    """
    def __init__(self) -> None:
        self._indexes: List[int] = []
        self._values: List[Any] = []

    def set(self, index: int, value: Any) -> None:
        if index < 0:
            raise ValueError("negative index")
        pos = bisect_left(self._indexes, index)
        if pos < len(self._indexes) and self._indexes[pos] == index:
            self._values[pos] = value
        else:
            self._indexes.insert(pos, index)
            self._values.insert(pos, value)

    def get(self, index: int) -> Any:
        if index < 0:
            raise ValueError("negative index")
        pos = bisect_left(self._indexes, index)
        if pos < len(self._indexes) and self._indexes[pos] == index:
            return self._values[pos]
        return None

    def items(self) -> List[Tuple[int, Any]]:
        return list(zip(self._indexes, self._values))
